export class PlaywrightDevPage {
  constructor(page) {
    this.page = page
    this.getStartedLink = page.locator('a', { hasText: 'Get started' })
  }
  async goto() { await this.page.goto('https://playwright.dev') }
  async getStarted() { await this.getStartedLink.first().click() }
}
